"""Retain54 uncomputed invalid parents, finish abandoned, reserve corrected definitions."""
import copy,json,subprocess,sys
from run import ROOT,R,reg,sha,put,rel,now,call
assert not(R/'report.json').exists() and not(R/'plan_corrected.json').exists()
rows=json.loads((R/'batch.json').read_text());receipts=json.loads((R/'reserve.json').read_text());assert len(rows)==len(receipts)==108 and all(x['exit_code']==0 for x in receipts)
put(R/'batch_original.json',rows);put(R/'reserve_original.json',receipts);invalid=[x for x in rows if x['scope']=='parent'];assert len(invalid)==54
report={'result_available':False,'new_financial_evaluations':0,'reason':'Parent ETH_trend_lookback_days was21/31but duplicate trend_filter_lookback_days stayed28. Detected before any financial evaluation. Native54 definitions remain valid/reserved.','invalid_count':54,'original_plan':rel(R/'plan.json'),'original_plan_sha256':sha(R/'plan.json'),'invalid_definitions':[{'name':x['name'],'fingerprint':x['fingerprint'],'spec':x['spec'],'spec_sha256':sha(ROOT/x['spec'])} for x in invalid],'recovery':'Retain originalspecs/plan/batch/reserve; finish only invalid54 abandoned/false; correct alias and successfully reserve corrected54 before calculations.'};put(R/'invalid_spec_report.json',report);commands=[]
for row in invalid:
 commands.append(call('finish',row,'abandoned',rel(R/'invalid_spec_report.json')));put(R/'correction_commands.json',commands)
plan=copy.deepcopy(json.loads((R/'plan.json').read_text()));plan['frozen_at_utc']=now();plan['definition_correction']={'before_actual_evaluation':True,'original_plan':rel(R/'plan.json'),'original_plan_sha256':sha(R/'plan.json'),'invalid_report':rel(R/'invalid_spec_report.json'),'invalid_report_sha256':sha(R/'invalid_spec_report.json'),'retained_uncomputed_abandoned_definitions':54,'actual_financial_configurations_unchanged':108,'change':'Set duplicate parent trend_filter_lookback_days equal to predeclared ETH_trend_lookback_days21/31, no strategy rules/data/cost/gates or native definition change.'};put(R/'plan_corrected.json',plan)
(R/'specs_corrected').mkdir();corrected=[];newreceipts=[]
for row in invalid:
 sp=json.loads((ROOT/row['spec']).read_text());S=row['trend_filter_lookback_days'];assert sp['parameters']['ETH_trend_lookback_days']==S and sp['parameters']['trend_filter_lookback_days']==28;sp['parameters']['trend_filter_lookback_days']=S;sp['validation_plan']=rel(R/'plan_corrected.json');path=R/'specs_corrected'/(row['name']+'.json');put(path,sp);fp=reg.fingerprint(sp);assert fp!=row['fingerprint'];new={**row,'spec':rel(path),'fingerprint':fp,'replaces_abandoned_fingerprint':row['fingerprint'],'original_invalid_spec':row['spec'],'original_invalid_spec_sha256':sha(ROOT/row['spec'])};corrected.append(new);receipt=call('reserve',new);commands.append(receipt);newreceipts.append(receipt);put(R/'correction_commands.json',commands)
native=[x for x in rows if x['scope']=='native'];put(R/'batch.json',native+corrected);put(R/'reserve.json',[x for x in receipts if x['name'] in {n['name'] for n in native}]+newreceipts)
p=subprocess.run([sys.executable,str(R/'check_spec_aliases.py')],cwd=ROOT,capture_output=True,text=True);(R/'alias_preflight_recovery.log').write_text(p.stdout+p.stderr);commands.append({'command':[sys.executable,rel(R/'check_spec_aliases.py')],'cwd':str(ROOT),'exit_code':p.returncode,'log':rel(R/'alias_preflight_recovery.log'),'stdout':p.stdout,'stderr':p.stderr});put(R/'correction_commands.json',commands);assert p.returncode==0
print('CORRECTED54_RESERVED54_NATIVE_VALID_NO_FINANCIAL_RESULT_REWRITTEN',sha(R/'plan_corrected.json'),flush=True)
